    private static string GetToken<TEnum>(TEnum value, string[] tokens) where TEnum : struct, Enum {
        int index = Convert.ToInt32(value, CultureInfo.InvariantCulture);
        if ((uint)index >= (uint)tokens.Length) throw new ArgumentOutOfRangeException(nameof(value), value, $"Unsupported {typeof(TEnum).Name} value.");
        return tokens[index];
    }

    private static int FindToken(string token, string[] tokens, string enumName) {
        int index = Array.IndexOf(tokens, token);
        if (index < 0) throw new ArgumentOutOfRangeException(nameof(token), token, $"Unsupported {enumName} token.");
        return index;
    }
